#"'!/bin/bash
# usage: mhb.sh BODYFILE [VERSION]  -> error-check + heartbeat estimate for body BODYFILE (path to file with proof body only)
W=$(cd "$(dirname "$0")/.." && pwd)
B=$(basename "$1" .lean); V=${2:-v4.31.0}
P=/localhome/milikic/proof-reduction-competition/.proof-eval-projects/arklib-$V
F="$W/runtime_tmp/mh_$B.lean"
mk () { { cat "$W/runtime_tmp/hdr.lean"; echo "set_option maxHeartbeats $1 in";
    sed '"'s/"'^theorem fold_advances_evaluation_poly$/theorem TEST_fold_adv/'"' \""'$W/notes/stmtonly.lean";
    cat "$1"; printf '"'end Binius.BinaryBasefold\\n'; } > \""'$F"; }
run () { mk $1; OUT=$(bash "$W/notes/env.sh" "$V" "$F" 2>&1);
  if echo "$OUT" | grep -q "maximum number of heartbeats"; then echo T;
  elif echo "$OUT" | grep -qE "error|warning"; then echo "E: $(echo "$OUT"|head -20)"; else echo P; fi; }
R=$(run 100000000)
if [ "$R" != "P" ]; then echo "$B ERR"; echo "$R" | head -20; exit 1; fi
LO=1; HI=1000
while [ "$(run $HI)" = "T" ]; do LO=$HI; HI=$((HI*2)); done
if [ "$(run $LO)" != "T" ]; then echo "$B est<1000"; exit 0; fi
for i in $(seq 1 12); do MID=$(( (LO+HI)/2 )); if [ "$(run $MID)" = "T" ]; then LO=$MID; else HI=$MID; fi; done
echo "$B est_hb=$(( (LO+HI)/2 ))"
EOF
chmod +x mhb.sh && time bash mhb.sh bBEST.lean'

